sessions.style:
/* ————————————————————————————————————————————————
   Single-theme by design: this is a stage/projection surface and the
   embedded social graphics are built for a dark ground.
   Palette: warm near-black w/ orange hue bias + the letspepper heat ladder
   (green→yellow→orange→red) used only where it encodes meaning.
   ———————————————————————————————————————————————— */
:root {
  color-scheme: dark;
  --bg: #171310;
  --panel: #211a14;
  --panel2: #2a2119;
  --line: #3a2d21;
  --text: #f2eadf;
  --dim: #a5937e;
  --faint: #7a6b58;
  --heat: #f97316;
  --heat-soft: rgba(249, 115, 22, 0.13);
  --mild: #4ade80;
  --medium: #facc15;
  --extreme: #ef4444;
  --display: "Avenir Next Condensed", "Arial Narrow", "Roboto Condensed", sans-serif;
  --body: "Avenir Next", "Segoe UI", system-ui, sans-serif;
  --mono: "SF Mono", ui-monospace, "Cascadia Code", Consolas, "Roboto Mono", monospace;
}

html { scroll-snap-type: y proximity; }
body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--body);
  font-size: 16px;
  line-height: 1.55;
  margin: 0;
}
* { box-sizing: border-box; }
img { max-width: 100%; display: block; }

/* —— chrome: heat progress bar + slide rail ——————————— */
.heatbar {
  position: fixed; top: 0; left: 0; height: 4px; width: 100%;
  transform-origin: 0 50%; transform: scaleX(0);
  background: linear-gradient(90deg, var(--mild), var(--medium) 40%, var(--heat) 72%, var(--extreme));
  z-index: 50;
}
.rail {
  position: fixed; left: 18px; top: 50%; translate: 0 -50%;
  display: flex; flex-direction: column; gap: 10px; z-index: 40;
}
.rail a {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--line); display: block;
}
.rail a.on { background: var(--heat); }
.rail a:focus-visible { outline: 2px solid var(--heat); outline-offset: 3px; }
@media (max-width: 900px) { .rail { display: none; } }

/* —— slide scaffold ————————————————————————————— */
.slide {
  min-height: 100svh;
  display: flex; align-items: center;
  padding: clamp(48px, 8vh, 88px) clamp(20px, 6vw, 72px);
  scroll-snap-align: start;
  border-bottom: 1px solid var(--line);
}
.wrap { width: min(1060px, 100%); margin-inline: auto; }

.eyebrow {
  font-family: var(--mono); font-size: 12px; letter-spacing: 0.14em;
  text-transform: uppercase; color: var(--dim); margin: 0 0 14px;
}
.eyebrow b { color: var(--heat); font-weight: 600; margin-right: 10px; }
h2 {
  font-family: var(--display); font-weight: 700; text-transform: uppercase;
  font-size: clamp(36px, 5.2vw, 58px); line-height: 0.96;
  letter-spacing: 0.005em; margin: 0 0 22px; text-wrap: balance;
}
.lede { font-size: clamp(16px, 1.9vw, 19px); color: var(--dim); max-width: 62ch; margin: 0 0 30px; }
.lede strong, p strong { color: var(--text); font-weight: 600; }

/* —— title slide ————————————————————————————— */
.title-slide { border-bottom-color: var(--heat); }
h1 {
  font-family: var(--display); font-weight: 700; text-transform: uppercase;
  font-size: clamp(74px, 14.5vw, 168px); line-height: 0.88;
  letter-spacing: 0.005em; margin: 18px 0 26px;
}
h1 .dot { color: var(--heat); }
.title-sub { font-size: clamp(17px, 2.1vw, 21px); color: var(--dim); max-width: 56ch; margin: 0 0 40px; }
.heatstrip { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; margin-bottom: 48px; }
.heatstrip .h {
  font-family: var(--mono); font-size: 11px; letter-spacing: 0.12em;
  padding: 4px 10px; border: 1px solid; border-radius: 3px;
}
.h.mild    { color: var(--mild);    border-color: color-mix(in srgb, var(--mild) 45%, transparent); }
.h.medium  { color: var(--medium);  border-color: color-mix(in srgb, var(--medium) 45%, transparent); }
.h.hot     { color: var(--heat);    border-color: color-mix(in srgb, var(--heat) 55%, transparent); background: var(--heat-soft); }
.h.extreme { color: var(--extreme); border-color: color-mix(in srgb, var(--extreme) 45%, transparent); }
.heatstrip .cue { font-family: var(--mono); font-size: 12px; color: var(--faint); margin-left: 6px; }
.hint { font-family: var(--mono); font-size: 12px; color: var(--faint); }
.hint kbd {
  font-family: inherit; border: 1px solid var(--line); border-bottom-width: 2px;
  border-radius: 4px; padding: 1px 7px; margin: 0 2px; color: var(--dim);
}

/* —— generic building blocks ————————————————————— */
.cols { display: grid; gap: 18px; }
.cols.c2 { grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); }
.cols.c3 { grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); }
.panel {
  background: var(--panel); border: 1px solid var(--line); border-radius: 8px;
  padding: 22px 24px;
}
.panel h3 {
  font-family: var(--display); text-transform: uppercase; font-weight: 600;
  font-size: 22px; letter-spacing: 0.02em; margin: 0 0 10px; line-height: 1.1;
}
.panel p { margin: 0 0 10px; font-size: 15px; color: var(--dim); }
.panel p:last-child { margin-bottom: 0; }
.ptag {
  font-family: var(--mono); font-size: 10.5px; letter-spacing: 0.14em;
  text-transform: uppercase; color: var(--heat); margin: 0 0 12px;
}

ul.tight { margin: 0; padding-left: 20px; color: var(--dim); }
ul.tight li { margin-bottom: 12px; padding-left: 4px; }
ul.tight li::marker { color: var(--heat); }

/* —— asset imagery ————————————————————————————— */
.shots { display: flex; flex-wrap: wrap; gap: 18px; align-items: flex-start; }
.shot { flex: 1 1 180px; max-width: 250px; }
.shot.wide { max-width: 320px; }
.shot img { border-radius: 6px; border: 1px solid var(--line); width: 100%; height: auto; }
.shot figcaption { font-family: var(--mono); font-size: 11px; letter-spacing: 0.08em; color: var(--dim); margin-top: 9px; }
.shot figcaption b { color: var(--heat); font-weight: 600; }
figure { margin: 0; }

/* —— message log ————————————————————————————— */
.log { display: flex; flex-direction: column; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }
.msg {
  display: grid; grid-template-columns: 44px 108px 1fr; gap: 14px;
  padding: 12px 18px; border-bottom: 1px solid var(--line); align-items: baseline;
  background: var(--panel);
}
.msg:nth-child(even) { background: var(--bg); }
.msg:last-child { border-bottom: 0; }
.msg .no { font-family: var(--mono); font-size: 12px; color: var(--faint); font-variant-numeric: tabular-nums; }
.kind {
  font-family: var(--mono); font-size: 9.5px; letter-spacing: 0.1em; text-transform: uppercase;
  padding: 2px 7px; border-radius: 3px; border: 1px solid; justify-self: start; white-space: nowrap;
}
.kind.steer { color: var(--heat);    border-color: color-mix(in srgb, var(--heat) 50%, transparent);    background: color-mix(in srgb, var(--heat) 10%, transparent); }
.kind.qual  { color: var(--medium);  border-color: color-mix(in srgb, var(--medium) 45%, transparent);  background: color-mix(in srgb, var(--medium) 8%, transparent); }
.kind.judge { color: var(--mild);    border-color: color-mix(in srgb, var(--mild) 45%, transparent);    background: color-mix(in srgb, var(--mild) 8%, transparent); }
.kind.go    { color: var(--extreme); border-color: color-mix(in srgb, var(--extreme) 50%, transparent); background: color-mix(in srgb, var(--extreme) 10%, transparent); }
.msg .q { font-family: var(--mono); font-size: 13px; line-height: 1.45; margin: 0; }
.msg .a { font-size: 12.5px; color: var(--faint); margin: 4px 0 0; }
@media (max-width: 640px) {
  .msg { grid-template-columns: 34px 1fr; }
  .msg .kind { grid-column: 2; margin-bottom: 2px; }
  .msg .body { grid-column: 2; }
}
.legend { display: flex; flex-wrap: wrap; gap: 18px; margin: 16px 2px 0; font-family: var(--mono); font-size: 11px; letter-spacing: 0.08em; color: var(--dim); }
.legend i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; margin-right: 7px; }
.redact { color: var(--faint); }
.fnote { font-family: var(--mono); font-size: 11px; color: var(--faint); margin-top: 14px; }

/* —— principles ————————————————————————————— */
.prin { display: flex; flex-direction: column; gap: 14px; }
.prin .p { display: grid; grid-template-columns: 64px 1fr; gap: 20px; padding: 20px 22px; background: var(--panel); border: 1px solid var(--line); border-radius: 8px; align-items: start; }
.prin .n { font-family: var(--display); font-weight: 700; font-size: 44px; line-height: 1; color: var(--heat); font-variant-numeric: tabular-nums; }
.prin h3 { font-family: var(--display); text-transform: uppercase; font-weight: 600; font-size: 21px; margin: 2px 0 6px; letter-spacing: 0.02em; }
.prin p { margin: 0; font-size: 15px; color: var(--dim); max-width: 74ch; }

/* —— pipeline ————————————————————————————— */
.flow { display: flex; flex-wrap: wrap; gap: 8px; align-items: stretch; margin-bottom: 26px; }
.node {
  background: var(--panel); border: 1px solid var(--line); border-radius: 8px;
  padding: 12px 13px; flex: 1 1 116px; min-width: 110px; max-width: 260px;
}
.node .t { font-family: var(--mono); font-size: 12.5px; font-weight: 600; letter-spacing: 0.02em; }
.node .s { font-family: var(--mono); font-size: 10.5px; color: var(--faint); margin-top: 6px; letter-spacing: 0.04em; }
.node .who { display: inline-block; font-family: var(--mono); font-size: 9.5px; letter-spacing: 0.1em; text-transform: uppercase; margin-top: 10px; padding: 2px 7px; border-radius: 3px; }
.who.human { color: var(--mild); background: color-mix(in srgb, var(--mild) 10%, transparent); }
.who.agent { color: var(--heat); background: var(--heat-soft); }
.who.script { color: var(--dim); background: color-mix(in srgb, var(--dim) 12%, transparent); }
.arrow { align-self: center; color: var(--heat); font-family: var(--mono); font-size: 18px; }
@media (max-width: 760px) { .arrow { display: none; } .node { flex-basis: 44%; } }

/* —— failure / escalation cards use .panel; accent variants —— */
.panel.warn { border-color: color-mix(in srgb, var(--extreme) 40%, var(--line)); }
.panel.warn .ptag { color: var(--extreme); }
.panel .lesson { font-family: var(--mono); font-size: 12px; color: var(--text); border-top: 1px solid var(--line); padding-top: 12px; margin-top: 14px; letter-spacing: 0.02em; }
.panel .lesson b { color: var(--heat); }

/* —— mapping table ————————————————————————————— */
.map { display: flex; flex-direction: column; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; margin-bottom: 30px; }
.maprow { display: grid; grid-template-columns: minmax(180px, 1fr) 2fr; gap: 16px; padding: 16px 20px; border-bottom: 1px solid var(--line); background: var(--panel); }
.maprow:nth-child(even) { background: var(--bg); }
.maprow:last-child { border-bottom: 0; }
.maprow .k { font-family: var(--display); text-transform: uppercase; font-weight: 600; font-size: 18px; letter-spacing: 0.02em; line-height: 1.2; }
.maprow .v { font-size: 14.5px; color: var(--dim); }

/* —— appendix ————————————————————————————— */
.stack { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 30px; }
.stack span, .stack a {
  font-family: var(--mono); font-size: 12px; color: var(--dim); text-decoration: none;
  border: 1px solid var(--line); border-radius: 4px; padding: 5px 11px; background: var(--panel);
}
.stack a { color: var(--heat); }
.colophon { border-top: 1px solid var(--line); margin-top: 34px; padding-top: 18px; font-family: var(--mono); font-size: 12px; color: var(--faint); line-height: 1.7; }
.colophon b { color: var(--dim); font-weight: 600; }

a { color: var(--heat); }
a:focus-visible { outline: 2px solid var(--heat); outline-offset: 2px; }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}
@media print {
  .heatbar, .rail, .hint { display: none; }
  .slide { min-height: auto; break-after: page; }
}

/* ————————————————————————————————————————————————
   Demo 02 identity: cool terminal charcoal + amber phosphor. The signature
   device is the pairing — terminal window on one side, browser viewport on
   the other — because "the terminal drives a real browser" IS the thesis.
   Single-theme by design (a terminal is a committed dark world).
   ———————————————————————————————————————————————— */
:root {
  color-scheme: dark;
  --bg: #0f1317;
  --panel: #151b21;
  --panel2: #10151a;
  --line: #27313b;
  --text: #e6edf3;
  --dim: #93a4b3;
  --faint: #5d6c79;
  --amber: #f2b13d;
  --amber-soft: rgba(242, 177, 61, 0.12);
  --ok: #7ee787;
  --display: "Avenir Next Condensed", "Arial Narrow", "Roboto Condensed", sans-serif;
  --body: "Avenir Next", "Segoe UI", system-ui, sans-serif;
  --mono: "SF Mono", ui-monospace, "Cascadia Code", Consolas, "Roboto Mono", monospace;
}

html { scroll-snap-type: y proximity; }
body {
  background: var(--bg); color: var(--text);
  font-family: var(--body); font-size: 16px; line-height: 1.55; margin: 0;
}
* { box-sizing: border-box; }
img { max-width: 100%; display: block; }

.progress {
  position: fixed; top: 0; left: 0; height: 4px; width: 100%;
  transform-origin: 0 50%; transform: scaleX(0);
  background: linear-gradient(90deg, #6d4f16, var(--amber));
  z-index: 50;
}
.rail {
  position: fixed; left: 18px; top: 50%; translate: 0 -50%;
  display: flex; flex-direction: column; gap: 10px; z-index: 40;
}
.rail a { width: 8px; height: 8px; border-radius: 50%; background: var(--line); display: block; }
.rail a.on { background: var(--amber); }
.rail a:focus-visible { outline: 2px solid var(--amber); outline-offset: 3px; }
@media (max-width: 900px) { .rail { display: none; } }

.slide {
  min-height: 100svh; display: flex; align-items: center;
  padding: clamp(48px, 8vh, 88px) clamp(20px, 6vw, 72px);
  scroll-snap-align: start; border-bottom: 1px solid var(--line);
}
.wrap { width: min(1060px, 100%); margin-inline: auto; }

.eyebrow {
  font-family: var(--mono); font-size: 12px; letter-spacing: 0.14em;
  text-transform: uppercase; color: var(--dim); margin: 0 0 14px;
}
.eyebrow b { color: var(--amber); font-weight: 600; margin-right: 10px; }
h2 {
  font-family: var(--display); font-weight: 700; text-transform: uppercase;
  font-size: clamp(36px, 5.2vw, 58px); line-height: 0.96; margin: 0 0 22px; text-wrap: balance;
}
.lede { font-size: clamp(16px, 1.9vw, 19px); color: var(--dim); max-width: 64ch; margin: 0 0 30px; }
.lede strong, p strong { color: var(--text); font-weight: 600; }

.title-slide { border-bottom-color: var(--amber); }
h1 {
  font-family: var(--display); font-weight: 700; text-transform: uppercase;
  font-size: clamp(58px, 10.5vw, 126px); line-height: 0.9; margin: 18px 0 26px; text-wrap: balance;
}
h1 .dot { color: var(--amber); }
.title-sub { font-size: clamp(17px, 2.1vw, 21px); color: var(--dim); max-width: 58ch; margin: 0 0 40px; }
.hint { font-family: var(--mono); font-size: 12px; color: var(--faint); }
.hint kbd {
  font-family: inherit; border: 1px solid var(--line); border-bottom-width: 2px;
  border-radius: 4px; padding: 1px 7px; margin: 0 2px; color: var(--dim);
}

/* —— terminal + viewport frames ————————————————— */
.term { background: var(--panel2); border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }
.term-bar, .vp-bar {
  display: flex; align-items: center; gap: 6px; padding: 9px 12px;
  background: var(--panel); border-bottom: 1px solid var(--line);
}
.term-bar i { width: 10px; height: 10px; border-radius: 50%; background: #33404c; }
.term-bar span, .vp-bar .url { font-family: var(--mono); font-size: 11px; color: var(--faint); margin-left: 8px; }
.term pre { margin: 0; padding: 15px 17px; font-family: var(--mono); font-size: 12.5px; line-height: 1.65; overflow-x: auto; }
.term .p { color: var(--ok); }
.term .c { color: var(--text); }
.term .o { color: var(--dim); }
.term .cm { color: var(--faint); }
.viewport { border: 1px solid var(--line); border-radius: 8px; overflow: hidden; background: var(--panel2); }
.vp-bar .url {
  margin-left: 4px; background: var(--panel2); border: 1px solid var(--line);
  border-radius: 99px; padding: 3px 12px; flex: 1; color: var(--dim);
}
.viewport img { width: 100%; height: auto; }
.cap { font-family: var(--mono); font-size: 11.5px; letter-spacing: 0.05em; color: var(--dim); margin: 10px 2px 0; }
.cap b { color: var(--amber); font-weight: 600; }

.pair { display: grid; grid-template-columns: 1.15fr 1fr; gap: 18px; align-items: start; }
@media (max-width: 820px) { .pair { grid-template-columns: 1fr; } }
.runs { display: flex; flex-direction: column; gap: 28px; }

/* —— tax bars ————————————————————————————————— */
.bars { display: flex; flex-direction: column; gap: 16px; margin: 6px 0 30px; }
.bar { display: grid; grid-template-columns: 220px 1fr; gap: 14px; align-items: center; }
.bar .l { font-family: var(--mono); font-size: 12.5px; color: var(--dim); text-align: right; }
.bar .track { display: flex; align-items: center; gap: 12px; }
.bar .fill { height: 26px; border-radius: 4px; background: #33404c; }
.bar.hot .fill { background: var(--amber); }
.bar .n { font-family: var(--mono); font-size: 12.5px; color: var(--text); white-space: nowrap; font-variant-numeric: tabular-nums; }
@media (max-width: 640px) { .bar { grid-template-columns: 1fr; } .bar .l { text-align: left; } }

/* —— generic blocks (shared scaffold vocabulary) ————— */
.cols { display: grid; gap: 18px; }
.cols.c2 { grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); }
.cols.c3 { grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); }
.panel { background: var(--panel); border: 1px solid var(--line); border-radius: 8px; padding: 22px 24px; }
.panel h3 {
  font-family: var(--display); text-transform: uppercase; font-weight: 600;
  font-size: 22px; letter-spacing: 0.02em; margin: 0 0 10px; line-height: 1.1;
}
.panel p { margin: 0 0 10px; font-size: 15px; color: var(--dim); }
.panel p:last-child { margin-bottom: 0; }
.ptag {
  font-family: var(--mono); font-size: 10.5px; letter-spacing: 0.14em;
  text-transform: uppercase; color: var(--amber); margin: 0 0 12px;
}
.panel .lesson {
  font-family: var(--mono); font-size: 12px; color: var(--text);
  border-top: 1px solid var(--line); padding-top: 12px; margin-top: 14px; letter-spacing: 0.02em;
}
.panel .lesson b { color: var(--amber); }

/* —— command table ———————————————————————————— */
.cmds { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 1px; background: var(--line); border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }
.cmd-row { background: var(--panel); padding: 13px 18px; display: grid; grid-template-columns: 152px 1fr; gap: 12px; align-items: baseline; }
.cmd-row b { font-family: var(--mono); font-size: 12.5px; color: var(--amber); font-weight: 600; }
.cmd-row span { font-size: 13.5px; color: var(--dim); }

.stack { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 30px; }
.stack span, .stack a {
  font-family: var(--mono); font-size: 12px; color: var(--dim); text-decoration: none;
  border: 1px solid var(--line); border-radius: 4px; padding: 5px 11px; background: var(--panel);
}
.stack a { color: var(--amber); }
.colophon { border-top: 1px solid var(--line); margin-top: 34px; padding-top: 18px; font-family: var(--mono); font-size: 12px; color: var(--faint); line-height: 1.7; }
.colophon b { color: var(--dim); font-weight: 600; }

a { color: var(--amber); }
a:focus-visible { outline: 2px solid var(--amber); outline-offset: 2px; }

@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }
@media print {
  .progress, .rail, .hint { display: none; }
  .slide { min-height: auto; break-after: page; }
}

/* ————————————————————————————————————————————————
   Demo 03 identity: incident-report-on-paper. Light ground (the first light
   deck in the series), enforcement-red accent, dark terminal exhibits.
   Structure device: EXHIBIT A-D — each guard is evidence, presented with its
   origin audit and its real deny message. Single-theme by design.
   ———————————————————————————————————————————————— */
:root {
  color-scheme: light;
  --paper: #f4f2ec;
  --card: #fdfcf9;
  --ink: #1e1f21;
  --dim: #5f5b52;
  --faint: #8d8778;
  --line: #ddd7c9;
  --red: #c2382f;
  --red-soft: rgba(194, 56, 47, 0.07);
  --pass: #2e7d4f;
  --term-bg: #16181b;
  --term-line: #2b2f34;
  --term-text: #dfe5ea;
  --term-dim: #8a94a0;
  --display: "Avenir Next Condensed", "Arial Narrow", "Roboto Condensed", sans-serif;
  --body: "Avenir Next", "Segoe UI", system-ui, sans-serif;
  --mono: "SF Mono", ui-monospace, "Cascadia Code", Consolas, "Roboto Mono", monospace;
}

html { scroll-snap-type: y proximity; }
body {
  background: var(--paper); color: var(--ink);
  font-family: var(--body); font-size: 16px; line-height: 1.55; margin: 0;
}
* { box-sizing: border-box; }

.progress {
  position: fixed; top: 0; left: 0; height: 4px; width: 100%;
  transform-origin: 0 50%; transform: scaleX(0);
  background: var(--red); z-index: 50;
}
.rail {
  position: fixed; left: 18px; top: 50%; translate: 0 -50%;
  display: flex; flex-direction: column; gap: 10px; z-index: 40;
}
.rail a { width: 8px; height: 8px; border-radius: 50%; background: var(--line); display: block; }
.rail a.on { background: var(--red); }
.rail a:focus-visible { outline: 2px solid var(--red); outline-offset: 3px; }
@media (max-width: 900px) { .rail { display: none; } }

.slide {
