   signature device is the persona quad: one row, four cards, same
   catalog, four different layouts. Pass/fail carries only the honest-
   failure slide. Single-theme by design.
   ———————————————————————————————————————————————— */
:root {
  color-scheme: dark;
  --bg: #170a1c;
  --panel: #241030;
  --panel2: #1c0c26;
  --line: #3d1f4a;
  --text: #f5eef9;
  --dim: #c9b3d4;
  --faint: #8a6d97;
  --fuchsia: #d946ef;
  --fuchsia-soft: rgba(217, 70, 239, 0.12);
  --pass: #4ade80;
  --fail: #f87171;
  --display: "Avenir Next Condensed", "Arial Narrow", "Roboto Condensed", sans-serif;
  --body: "Avenir Next", "Segoe UI", system-ui, sans-serif;
  --mono: "SF Mono", ui-monospace, "Cascadia Code", Consolas, "Roboto Mono", monospace;
}

html { scroll-snap-type: y proximity; }
body {
  background: var(--bg); color: var(--text);
  font-family: var(--body); font-size: 16px; line-height: 1.55; margin: 0;
}
* { box-sizing: border-box; }

.progress {
  position: fixed; top: 0; left: 0; height: 4px; width: 100%;
  transform-origin: 0 50%; transform: scaleX(0);
  background: linear-gradient(90deg, #86198f, var(--fuchsia)); z-index: 50;
}
