  --faint: #68758b;
  --amber: #ffb454;
  --amber-soft: rgba(255, 180, 84, .12);
  --blue: #84a9ff;
  --green: #62d3a6;
  --red: #ff817a;
  --violet: #b99dff;
  --display: "Avenir Next Condensed", "Arial Narrow", "Roboto Condensed", sans-serif;
  --body: "Avenir Next", "Segoe UI", system-ui, sans-serif;
  --mono: "SF Mono", ui-monospace, "Cascadia Code", Consolas, monospace;
}

* { box-sizing: border-box; }
html { scroll-snap-type: y proximity; }
body {
  margin: 0;
  background:
    linear-gradient(rgba(255,255,255,.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.025) 1px, transparent 1px),
    var(--bg);
  background-size: 48px 48px;
  color: var(--ink);
  font: 16px/1.55 var(--body);
}
a { color: var(--amber); }
a:focus-visible, button:focus-visible, input:focus-visible {
  outline: 2px solid var(--amber);
  outline-offset: 3px;
}
.progress {
  position: fixed;
  inset: 0 auto auto 0;
  width: 100%;
  height: 4px;
  transform: scaleX(0);
  transform-origin: 0 50%;
  background: linear-gradient(90deg, var(--blue), var(--amber));
  z-index: 50;
}
.rail {
  position: fixed;
  left: 18px;
  top: 50%;
  translate: 0 -50%;
  display: flex;
  flex-direction: column;
  gap: 10px;
  z-index: 40;
}
.rail a {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--line);
}
.rail a.on { background: var(--amber); }
.slide {
  min-height: 100svh;
  display: flex;
  align-items: center;
  padding: clamp(52px, 8vh, 92px) clamp(20px, 6vw, 78px);
  border-bottom: 1px solid var(--line);
  scroll-snap-align: start;
}
.wrap { width: min(1120px, 100%); margin-inline: auto; }
.eyebrow {
  margin: 0 0 15px;
  color: var(--muted);
  font: 12px/1.4 var(--mono);
  letter-spacing: .14em;
  text-transform: uppercase;
}
.eyebrow b { color: var(--amber); margin-right: 10px; }
h1, h2, h3 {
  margin: 0;
  font-family: var(--display);
  font-weight: 750;
  line-height: .94;
  text-wrap: balance;
}
h1, h2 { text-transform: uppercase; }
h1 { max-width: 920px; font-size: clamp(58px, 11vw, 140px); }
h2 { max-width: 900px; margin-bottom: 22px; font-size: clamp(38px, 6.2vw, 72px); }
h3 { font-size: 24px; }
.mark { color: var(--amber); }
.title-sub, .lede { max-width: 70ch; color: var(--muted); }
.title-sub { margin: 28px 0 34px; font-size: clamp(17px, 2vw, 21px); }
.lede { margin: 0 0 28px; font-size: clamp(16px, 1.8vw, 19px); }
.lede strong, p strong { color: var(--ink); font-weight: 650; }
.hint { color: var(--faint); font: 12px var(--mono); }
.hint kbd {
  border: 1px solid var(--line);
  border-bottom-width: 2px;
  border-radius: 4px;
  padding: 1px 7px;
  color: var(--muted);
  font: inherit;
}
.stamp {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 26px;
  padding: 7px 11px;
  border: 1px solid var(--line);
  color: var(--muted);
  font: 11px var(--mono);
  letter-spacing: .04em;
}
.stamp::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--amber); }
.cols { display: grid; gap: 15px; }
.c2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.c3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.panel {
  padding: 22px 24px;
  background: rgba(17, 23, 34, .92);
  border: 1px solid var(--line);
  border-radius: 10px;
}
.panel p { margin: 0; color: var(--muted); font-size: 15px; }
.tag {
  margin: 0 0 12px;
  color: var(--amber);
  font: 10.5px var(--mono);
  letter-spacing: .13em;
  text-transform: uppercase;
}
.panel h3 { margin-bottom: 10px; }
.panel.local { border-color: rgba(132, 169, 255, .48); }
.panel.frontier { border-color: rgba(255, 180, 84, .5); }
.panel.safe { border-color: rgba(98, 211, 166, .45); }
.panel.warning { border-color: rgba(255, 129, 122, .48); }

.bill {
  display: grid;
  grid-template-columns: 1fr 34px 1fr;
  gap: 12px;
  align-items: stretch;
}
.bill-side {
  display: grid;
  gap: 10px;
  padding: 18px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 10px;
}
.bill-side h3 { font-size: 29px; }
.bill-side.local h3 { color: var(--blue); }
.bill-side.cloud h3 { color: var(--amber); }
.bill-item {
  padding-top: 10px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 14px;
}
.bill-item b { display: block; margin-bottom: 2px; color: var(--ink); font-size: 15px; }
.versus { display: grid; place-items: center; color: var(--faint); font: 12px var(--mono); }

.route-grid { display: grid; gap: 10px; margin-top: 18px; }
.route {
  display: grid;
  grid-template-columns: 175px 1fr;
  gap: 16px;
  padding: 14px 16px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-left: 3px solid var(--acc);
  border-radius: 7px;
}
.route b { color: var(--acc); font: 12px var(--mono); letter-spacing: .05em; text-transform: uppercase; }
.route span { color: var(--muted); font-size: 14px; }

.formula {
  margin: 20px 0;
  padding: 18px 20px;
  background: var(--surface-2);
  border: 1px dashed var(--amber);
  border-radius: 8px;
  color: var(--ink);
  font: 14px/1.8 var(--mono);
}
.formula .op { color: var(--amber); }
.formula .hint-line { display: block; color: var(--faint); font-size: 11px; }

.calculator {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(260px, .7fr);
  gap: 16px;
  align-items: start;
}
.fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  padding: 18px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 10px;
}
.field { display: grid; gap: 6px; }
.field label { color: var(--muted); font: 11px/1.3 var(--mono); }
.field input {
  width: 100%;
  padding: 10px 11px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--surface-2);
  color: var(--ink);
  font: 14px var(--mono);
}
.field input::placeholder { color: var(--faint); }
.results {
  display: grid;
  gap: 10px;
  padding: 18px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: 10px;
}
.results h3 { color: var(--amber); font-size: 25px; }
.result {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding-top: 10px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 13px;
}
.result b { color: var(--ink); font: 650 14px var(--mono); text-align: right; }
.result-note { margin: 4px 0 0; color: var(--faint); font: 11px/1.5 var(--mono); }
.calc-note { grid-column: 1 / -1; color: var(--faint); font: 11px/1.5 var(--mono); }

.receipts { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 10px; }
.receipt {
  min-height: 130px;
  padding: 15px 16px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 8px;
}
.receipt b { display: block; margin-bottom: 11px; color: var(--faint); font: 10px var(--mono); letter-spacing: .11em; text-transform: uppercase; }
.receipt span { display: block; color: var(--green); font: 700 25px/1 var(--display); text-transform: uppercase; }
.receipt em { display: block; margin-top: 9px; color: var(--muted); font: normal 11px/1.4 var(--mono); }
.receipt.hold span { color: var(--amber); }

.decision {
  display: grid;
  grid-template-columns: 1.1fr 1fr 1fr;
  gap: 1px;
  overflow: hidden;
  background: var(--line);
  border: 1px solid var(--line);
  border-radius: 10px;
}
.decision > div { padding: 19px; background: var(--surface); }
.decision .head { color: var(--faint); font: 10px var(--mono); letter-spacing: .1em; text-transform: uppercase; }
.decision b { display: block; margin: 9px 0 6px; color: var(--ink); font: 700 22px/1 var(--display); text-transform: uppercase; }
.decision p { margin: 0; color: var(--muted); font-size: 14px; }

.table-wrap { overflow-x: auto; border: 1px solid var(--line); border-radius: 10px; background: var(--surface); }
table { width: 100%; border-collapse: collapse; min-width: 640px; font-size: 14px; }
th, td { padding: 13px 15px; border-bottom: 1px solid var(--line); text-align: left; vertical-align: top; }
tr:last-child td { border-bottom: 0; }
th { color: var(--faint); background: var(--surface-2); font: 10px var(--mono); letter-spacing: .1em; text-transform: uppercase; }
td { color: var(--muted); }
td b { color: var(--ink); font-weight: 650; }
td.score { color: var(--amber); font: 700 18px/1 var(--display); white-space: nowrap; }
.evidence-note { margin: 12px 0 0; color: var(--faint); font: 11px/1.55 var(--mono); }
.evidence-note strong { color: var(--muted); }
.stat-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; }
.stat { padding: 15px 16px; background: var(--surface); border: 1px solid var(--line); border-radius: 8px; }
.stat b { display: block; color: var(--amber); font: 700 27px/1 var(--display); }
.stat span { display: block; margin-top: 8px; color: var(--muted); font-size: 12px; }
.callout { margin-top: 16px; padding: 16px 18px; border-left: 3px solid var(--amber); background: var(--amber-soft); color: var(--muted); font-size: 14px; }
.callout strong { color: var(--ink); }

.steps { display: grid; gap: 11px; margin-top: 18px; }
.step {
  display: grid;
  grid-template-columns: 38px 1fr;
  gap: 14px;
  align-items: start;
  padding: 14px 16px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 8px;
}
.step-num { display: grid; place-items: center; width: 32px; height: 32px; border: 1px solid var(--amber); border-radius: 50%; color: var(--amber); font: 12px var(--mono); }
.step b { display: block; margin-bottom: 3px; color: var(--ink); }
.step span { color: var(--muted); font-size: 14px; }
.chips { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 23px; }
.chip { padding: 5px 10px; border: 1px solid var(--line); border-radius: 4px; color: var(--muted); font: 11px var(--mono); }
.chip.warn { border-color: rgba(255,129,122,.5); color: var(--red); }
.colophon { margin-top: 28px; padding-top: 16px; border-top: 1px solid var(--line); color: var(--faint); font: 11px/1.65 var(--mono); }
.colophon b { color: var(--muted); }

@media (max-width: 900px) {
  .receipts { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .calculator { grid-template-columns: 1fr; }
  .stat-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 760px) {
  .rail { display: none; }
  .c2, .c3, .bill, .decision { grid-template-columns: 1fr; }
  .versus { min-height: 22px; }
  .route { grid-template-columns: 1fr; gap: 6px; }
  .fields { grid-template-columns: 1fr; }
  .receipts { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 460px) {
  .slide { padding-inline: 18px; }
  h1 { font-size: clamp(48px, 15vw, 76px); }
  .receipts { grid-template-columns: 1fr; }
  .stat-grid { grid-template-columns: 1fr; }
}
@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }
@media print { .progress, .rail, .hint { display: none; } .slide { min-height: auto; break-after: page; } }
